using Clock=std::chrono::steady_clock;
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
void cb(cublasStatus_t e){if(e!=CUBLAS_STATUS_SUCCESS)throw std::runtime_error("cuBLAS error "+std::to_string(e));}
double us(Clock::time_point t){return std::chrono::duration<double,std::micro>(Clock::now()-t).count();}
std::ofstream csv;std::mutex output;
void row(const std::string& name,int src,int dst,size_t bytes,int rep,int iterations,double device,double wall,double bandwidth=0,double tflops=0,bool valid=true){std::lock_guard<std::mutex> lock(output);csv<<name<<','<<src<<','<<dst<<','<<bytes<<','<<rep<<','<<iterations<<','<<device<<','<<wall<<','<<bandwidth<<','<<tflops<<','<<valid<<'\n';csv.flush();}
struct Timer{cudaEvent_t a,b;Timer(){ck(cudaEventCreate(&a));ck(cudaEventCreate(&b));}void start(cudaStream_t s=0){ck(cudaEventRecord(a,s));}double stop(cudaStream_t s=0){ck(cudaEventRecord(b,s));ck(cudaEventSynchronize(b));float ms;ck(cudaEventElapsedTime(&ms,a,b));return ms*1000.;}~Timer(){cudaEventDestroy(a);cudaEventDestroy(b);}};
__global__ void noop(int* p){if(threadIdx.x==0&&blockIdx.x==0)*p=1;}
__global__ void triad(const float* a,const float* b,float* c,int n){for(int i=blockIdx.x*blockDim.x+threadIdx.x;i<n;i+=gridDim.x*blockDim.x)c[i]=a[i]+2.f*b[i];}
template<class T>__global__ void fill(T* a,size_t n,float value){for(size_t i=blockIdx.x*blockDim.x+threadIdx.x;i<n;i+=size_t(gridDim.x)*blockDim.x)a[i]=T(value);}
__global__ void verifyBytes(const unsigned char* a,size_t n,unsigned char value,int* errors){for(size_t i=blockIdx.x*blockDim.x+threadIdx.x;i<n;i+=size_t(gridDim.x)*blockDim.x)if(a[i]!=value)atomicAdd(errors,1);}
struct Pair{int src,dst;unsigned char *a,*b;cudaStream_t stream;size_t capacity;Pair(int s,int d,size_t cap):src(s),dst(d),capacity(cap){ck(cudaSetDevice(src));ck(cudaMalloc(&a,cap));ck(cudaMemset(a,src+1,cap));ck(cudaDeviceSynchronize());ck(cudaSetDevice(dst));ck(cudaMalloc(&b,cap));ck(cudaMemset(b,0,cap));ck(cudaStreamCreate(&stream));}
 void copy(size_t n){ck(cudaMemcpyPeerAsync(b,dst,a,src,n,stream));}void validate(size_t n){ck(cudaSetDevice(dst));int* e;ck(cudaMalloc(&e,4));ck(cudaMemset(e,0,4));verifyBytes<<<256,256,0,stream>>>(b,n,src+1,e);ck(cudaStreamSynchronize(stream));int bad;ck(cudaMemcpy(&bad,e,4,cudaMemcpyDeviceToHost));ck(cudaFree(e));if(bad)throw std::runtime_error("Peer payload corruption");}
 ~Pair(){cudaSetDevice(dst);cudaStreamDestroy(stream);cudaFree(b);cudaSetDevice(src);cudaFree(a);}};
void transfers(){std::vector<size_t> sizes={64,256,1024,4096,16384,65536,262144,1048576,4194304,16777216,67108864};
 for(int src=0;src<3;++src)for(int dst=0;dst<3;++dst)if(src!=dst){Pair p(src,dst,sizes.back());ck(cudaSetDevice(dst));Timer timer;
 for(size_t bytes:sizes){for(int i=0;i<4;++i)p.copy(bytes);ck(cudaStreamSynchronize(p.stream));int iters=bytes>=1048576?16:128;
 for(int rep=0;rep<7;++rep){auto wall=Clock::now();timer.start(p.stream);for(int i=0;i<iters;++i)p.copy(bytes);double device=timer.stop(p.stream)/iters;double elapsed=us(wall)/iters;row("peer_batch",src,dst,bytes,rep,iters,device,elapsed,bytes/device/1000.);
 auto one=Clock::now();p.copy(bytes);ck(cudaStreamSynchronize(p.stream));row("peer_roundtrip",src,dst,bytes,rep,1,0,us(one));}p.validate(bytes);}
 std::cout<<"pair "<<src<<" -> "<<dst<<" complete\n"<<std::flush;}
 // Explicit pinned-host staging fallback, serialized D2H then H2D.
 size_t sizesHost[]={64,4096,65536,1048576,16777216,67108864};unsigned char* host;ck(cudaMallocHost(&host,67108864));
 for(int src=0;src<3;++src)for(int dst=0;dst<3;++dst)if(src!=dst){Pair p(src,dst,67108864);for(size_t bytes:sizesHost)for(int rep=0;rep<7;++rep){auto t=Clock::now();ck(cudaSetDevice(src));ck(cudaMemcpy(host,p.a,bytes,cudaMemcpyDeviceToHost));ck(cudaSetDevice(dst));ck(cudaMemcpy(p.b,host,bytes,cudaMemcpyHostToDevice));double wall=us(t);row("host_staged_roundtrip",src,dst,bytes,rep,1,0,wall,bytes/wall/1000.);}p.validate(67108864);}ck(cudaFreeHost(host));
 auto traffic=[](std::vector<Pair*>& pairs,const char* label){const size_t bytes=67108864;const int iters=16;for(auto* p:pairs){ck(cudaSetDevice(p->dst));p->copy(bytes);ck(cudaStreamSynchronize(p->stream));}
 for(int rep=0;rep<7;++rep){auto t=Clock::now();for(auto* p:pairs){ck(cudaSetDevice(p->dst));for(int k=0;k<iters;++k)p->copy(bytes);}for(auto* p:pairs){ck(cudaSetDevice(p->dst));ck(cudaStreamSynchronize(p->stream));}double wall=us(t);row(label,pairs.size()==2?pairs[0]->src:-1,pairs.size()==2?pairs[0]->dst:-1,bytes,rep,iters,0,wall/iters,bytes*pairs.size()*iters/wall/1000.);}for(auto* p:pairs)p->validate(bytes);};
 for(int a=0;a<3;++a)for(int b=a+1;b<3;++b){Pair p(a,b,67108864),q(b,a,67108864);std::vector<Pair*> pairs{&p,&q};traffic(pairs,"peer_bidirectional_aggregate");}
 std::vector<Pair*> all;for(int a=0;a<3;++a)for(int b=0;b<3;++b)if(a!=b)all.push_back(new Pair(a,b,67108864));traffic(all,"peer_all_pairs_aggregate");for(auto* p:all)delete p;
}
void scheduling(int gpu){ck(cudaSetDevice(gpu));cudaStream_t stream;ck(cudaStreamCreate(&stream));int* p;ck(cudaMalloc(&p,4));noop<<<1,1,0,stream>>>(p);ck(cudaStreamSynchronize(stream));Timer timer;
 for(int rep=0;rep<21;++rep){auto t=Clock::now();ck(cudaDeviceSynchronize());row("idle_device_sync",gpu,-1,0,rep,1,0,us(t));t=Clock::now();noop<<<1,1,0,stream>>>(p);ck(cudaStreamSynchronize(stream));row("kernel_roundtrip",gpu,-1,0,rep,1,0,us(t));}
 const int nodes=128;for(int rep=0;rep<7;++rep){auto t=Clock::now();timer.start(stream);for(int i=0;i<nodes;++i)noop<<<1,1,0,stream>>>(p);double dev=timer.stop(stream);row("kernel_launch_batch",gpu,-1,0,rep,nodes,dev/nodes,us(t)/nodes);}
 cudaGraph_t graph;cudaGraphExec_t executable;ck(cudaStreamBeginCapture(stream,cudaStreamCaptureModeGlobal));for(int i=0;i<nodes;++i)noop<<<1,1,0,stream>>>(p);ck(cudaStreamEndCapture(stream,&graph));auto build=Clock::now();ck(cudaGraphInstantiate(&executable,graph,0));row("graph_instantiate",gpu,-1,0,0,nodes,0,us(build));ck(cudaGraphLaunch(executable,stream));ck(cudaStreamSynchronize(stream));
 for(int rep=0;rep<7;++rep){auto t=Clock::now();timer.start(stream);ck(cudaGraphLaunch(executable,stream));double dev=timer.stop(stream);row("graph_128_nodes",gpu,-1,0,rep,nodes,dev/nodes,us(t)/nodes);}ck(cudaGraphExecDestroy(executable));ck(cudaGraphDestroy(graph));ck(cudaFree(p));ck(cudaStreamDestroy(stream));}
void barriers(){for(int a=0;a<3;++a)for(int b=0;b<3;++b)if(a!=b){int *p,*q;cudaStream_t s,t;cudaEvent_t e;ck(cudaSetDevice(a));ck(cudaMalloc(&p,4));ck(cudaStreamCreate(&s));ck(cudaEventCreateWithFlags(&e,cudaEventDisableTiming));ck(cudaSetDevice(b));ck(cudaMalloc(&q,4));ck(cudaStreamCreate(&t));
 for(int rep=-3;rep<21;++rep){auto start=Clock::now();ck(cudaSetDevice(a));noop<<<1,1,0,s>>>(p);ck(cudaEventRecord(e,s));ck(cudaSetDevice(b));ck(cudaStreamWaitEvent(t,e,0));noop<<<1,1,0,t>>>(q);ck(cudaStreamSynchronize(t));if(rep>=0)row("cross_device_event_chain",a,b,0,rep,1,0,us(start));}ck(cudaFree(q));ck(cudaStreamDestroy(t));ck(cudaSetDevice(a));ck(cudaFree(p));ck(cudaStreamDestroy(s));ck(cudaEventDestroy(e));}}
void memory(int gpu){ck(cudaSetDevice(gpu));const int n=67108864;const size_t bytes=size_t(n)*4;float *a,*b,*c;ck(cudaMalloc(&a,bytes));ck(cudaMalloc(&b,bytes));ck(cudaMalloc(&c,bytes));fill<<<1024,256>>>(a,n,1);fill<<<1024,256>>>(b,n,2);triad<<<1024,256>>>(a,b,c,n);ck(cudaDeviceSynchronize());Timer timer;
 for(int rep=0;rep<7;++rep){auto t=Clock::now();timer.start();for(int i=0;i<16;++i)triad<<<1024,256>>>(a,b,c,n);double dev=timer.stop()/16;row("hbm_triad",gpu,-1,bytes,rep,16,dev,us(t)/16,3*bytes/dev/1000.);}float value;ck(cudaMemcpy(&value,c+n-1,4,cudaMemcpyDeviceToHost));if(value!=5)throw std::runtime_error("Triad incorrect");ck(cudaFree(a));ck(cudaFree(b));ck(cudaFree(c));
 unsigned char *host,*dev;ck(cudaMallocHost(&host,67108864));ck(cudaMalloc(&dev,67108864));std::fill(host,host+67108864,17);cudaStream_t stream;ck(cudaStreamCreate(&stream));for(size_t size:{size_t(64),size_t(4096),size_t(65536),size_t(1048576),size_t(16777216),size_t(67108864)})for(int direction=0;direction<2;++direction){auto copy=[&](){ck(cudaMemcpyAsync(direction?host:dev,direction?dev:host,size,direction?cudaMemcpyDeviceToHost:cudaMemcpyHostToDevice,stream));};copy();ck(cudaStreamSynchronize(stream));for(int rep=0;rep<7;++rep){auto t=Clock::now();timer.start(stream);for(int i=0;i<16;++i)copy();double d=timer.stop(stream)/16;row(direction?"pinned_d2h":"pinned_h2d",gpu,-1,size,rep,16,d,us(t)/16,size/d/1000.);}}ck(cudaFree(dev));ck(cudaFreeHost(host));ck(cudaStreamDestroy(stream));}
struct Gemm{int gpu,n,kind;void *a,*b,*c;cublasHandle_t handle;cudaStream_t stream;Gemm(int g,int k):gpu(g),n(k==1?2048:4096),kind(k){ck(cudaSetDevice(gpu));size_t count=size_t(n)*n,bytes=count*(kind==1?8:kind==2?2:4);ck(cudaMalloc(&a,bytes));ck(cudaMalloc(&b,bytes));ck(cudaMalloc(&c,count*(kind==1?8:4)));ck(cudaStreamCreate(&stream));cb(cublasCreate(&handle));cb(cublasSetStream(handle,stream));cb(cublasSetMathMode(handle,kind==2?CUBLAS_TENSOR_OP_MATH:CUBLAS_PEDANTIC_MATH));
 if(kind==0){fill<<<1024,256,0,stream>>>((float*)a,count,1.f/n);fill<<<1024,256,0,stream>>>((float*)b,count,1);}else if(kind==1){fill<<<1024,256,0,stream>>>((double*)a,count,1.f/n);fill<<<1024,256,0,stream>>>((double*)b,count,1);}else{fill<<<1024,256,0,stream>>>((__half*)a,count,1.f/n);fill<<<1024,256,0,stream>>>((__half*)b,count,1);}for(int i=0;i<3;++i)launch();ck(cudaStreamSynchronize(stream));}
 void launch(){float alpha=1,beta=0;double da=1,db=0;if(kind==0)cb(cublasSgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,n,n,&alpha,(float*)a,n,(float*)b,n,&beta,(float*)c,n));else if(kind==1)cb(cublasDgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,n,n,&da,(double*)a,n,(double*)b,n,&db,(double*)c,n));else cb(cublasGemmEx(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,n,n,&alpha,a,CUDA_R_16F,n,b,CUDA_R_16F,n,&beta,c,CUDA_R_32F,n,CUBLAS_COMPUTE_32F,CUBLAS_GEMM_DEFAULT_TENSOR_OP));}
 void bench(const char* label,int rep,int iters){ck(cudaSetDevice(gpu));Timer timer;auto wall=Clock::now();timer.start(stream);for(int i=0;i<iters;++i)launch();double d=timer.stop(stream)/iters;row(label,gpu,-1,0,rep,iters,d,us(wall)/iters,0,2.*n*n*n/d/1e6);}
 void validate(){ck(cudaSetDevice(gpu));for(int offset:{0,n*n/2,n*n-1}){double v;if(kind==1)ck(cudaMemcpy(&v,(double*)c+offset,8,cudaMemcpyDeviceToHost));else{float x;ck(cudaMemcpy(&x,(float*)c+offset,4,cudaMemcpyDeviceToHost));v=x;}if(std::abs(v-1)>1e-5)throw std::runtime_error("GEMM output mismatch");}}
 ~Gemm(){cudaSetDevice(gpu);cublasDestroy(handle);cudaStreamDestroy(stream);cudaFree(a);cudaFree(b);cudaFree(c);}};
void compute(){for(int kind=0;kind<3;++kind){const char* label=kind==0?"gemm_fp32_pedantic":kind==1?"gemm_fp64_pedantic":"gemm_fp16_tensor_fp32_accumulate";for(int gpu=0;gpu<3;++gpu){Gemm g(gpu,kind);for(int rep=0;rep<7;++rep)g.bench(label,rep,10);g.validate();}}
 std::vector<Gemm*> jobs;for(int i=0;i<3;++i)jobs.push_back(new Gemm(i,0));
 for(int rep=0;rep<7;++rep){std::atomic<int> ready{0};std::atomic<bool> go{false};std::vector<std::thread> threads;std::vector<std::exception_ptr> errors(3);
 for(int gpu=0;gpu<3;++gpu)threads.emplace_back([&,gpu](){try{ck(cudaSetDevice(gpu));ready++;while(!go.load())std::this_thread::yield();jobs[gpu]->bench("gemm_fp32_concurrent",rep,30);}catch(...){errors[gpu]=std::current_exception();}});
 while(ready<3)std::this_thread::yield();auto start=Clock::now();go=true;for(auto& t:threads)t.join();for(auto e:errors)if(e)std::rethrow_exception(e);double wall=us(start);row("gemm_fp32_all_gpu_aggregate",-1,-1,0,rep,30,0,wall/30,0,3.*2*4096*4096*4096*30/wall/1e6);}
 for(auto* g:jobs){g->validate();delete g;}}
void overlap(){// Copy 0->1 while GPU1 computes: compare combined host completion to isolated work.
 Pair p(0,1,67108864);Gemm g(1,0);const int count=32;for(int rep=0;rep<7;++rep){ck(cudaSetDevice(1));auto t=Clock::now();for(int i=0;i<count;++i)p.copy(p.capacity);ck(cudaStreamSynchronize(p.stream));double copy=us(t);t=Clock::now();for(int i=0;i<count;++i)g.launch();ck(cudaStreamSynchronize(g.stream));double compute=us(t);t=Clock::now();for(int i=0;i<count;++i)p.copy(p.capacity);for(int i=0;i<count;++i)g.launch();ck(cudaStreamSynchronize(p.stream));ck(cudaStreamSynchronize(g.stream));double both=us(t);row("overlap_copy_only",0,1,p.capacity,rep,count,0,copy/count);row("overlap_compute_only",1,-1,0,rep,count,0,compute/count);row("overlap_copy_plus_compute",0,1,p.capacity,rep,count,0,both/count);}p.validate(p.capacity);g.validate();}
void inventory(const std::string& path){int n,driver,runtime;ck(cudaGetDeviceCount(&n));ck(cudaDriverGetVersion(&driver));ck(cudaRuntimeGetVersion(&runtime));if(n!=3)throw std::runtime_error("Exactly three CUDA devices required");std::ofstream f(path);f<<"{\"driver_api\":"<<driver<<",\"runtime_api\":"<<runtime<<",\"devices\":[";
 for(int i=0;i<n;++i){cudaDeviceProp p;ck(cudaGetDeviceProperties(&p,i));if(std::string(p.name).find("A100")==std::string::npos)throw std::runtime_error("Unexpected GPU model");char bus[32];ck(cudaDeviceGetPCIBusId(bus,32,i));ck(cudaSetDevice(i));size_t free,total;ck(cudaMemGetInfo(&free,&total));cudaFuncAttributes attr;ck(cudaFuncGetAttributes(&attr,triad));int blocks;ck(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks,triad,256,0));if(i)f<<',';
 f<<"{\"id\":"<<i<<",\"name\":\""<<p.name<<"\",\"pci_bus\":\""<<bus<<"\",\"sm_count\":"<<p.multiProcessorCount<<",\"compute_major\":"<<p.major<<",\"compute_minor\":"<<p.minor<<",\"total_bytes\":"<<total<<",\"free_bytes\":"<<free<<",\"l2_bytes\":"<<p.l2CacheSize<<",\"warp_size\":"<<p.warpSize<<",\"max_threads_per_block\":"<<p.maxThreadsPerBlock<<",\"max_threads_per_sm\":"<<p.maxThreadsPerMultiProcessor<<",\"registers_per_sm\":"<<p.regsPerMultiprocessor<<",\"shared_memory_per_sm\":"<<p.sharedMemPerMultiprocessor<<",\"async_engines\":"<<p.asyncEngineCount<<",\"concurrent_kernels\":"<<p.concurrentKernels<<",\"memory_bus_bits\":"<<p.memoryBusWidth<<",\"reported_clock_khz\":"<<p.clockRate<<",\"reported_memory_clock_khz\":"<<p.memoryClockRate<<",\"triad_registers_per_thread\":"<<attr.numRegs<<",\"triad_max_resident_blocks_per_sm\":"<<blocks<<",\"triad_theoretical_occupancy\":"<<double(blocks*256)/p.maxThreadsPerMultiProcessor<<'}';}
 f<<"],\"peer_pairs\":[";bool first=true;for(int a=0;a<3;++a)for(int b=0;b<3;++b)if(a!=b){int access,rank,atomic;ck(cudaDeviceCanAccessPeer(&access,a,b));ck(cudaDeviceGetP2PAttribute(&rank,cudaDevP2PAttrPerformanceRank,a,b));ck(cudaDeviceGetP2PAttribute(&atomic,cudaDevP2PAttrNativeAtomicSupported,a,b));if(!first)f<<',';first=false;f<<"{\"device\":"<<a<<",\"peer\":"<<b<<",\"access\":"<<access<<",\"performance_rank\":"<<rank<<",\"native_atomics\":"<<atomic<<'}';if(access){ck(cudaSetDevice(a));auto e=cudaDeviceEnablePeerAccess(b,0);if(e==cudaErrorPeerAccessAlreadyEnabled)cudaGetLastError();else ck(e);}}f<<"]}\n";}
int main(int argc,char** argv){try{if(argc<2)throw std::runtime_error("Output directory required");std::string out=argv[1];if(argc>2&&std::string(argv[2])=="counter"){ck(cudaSetDevice(0));int* p;ck(cudaMalloc(&p,4));noop<<<1,1>>>(p);ck(cudaDeviceSynchronize());ck(cudaFree(p));return 0;}
 csv.open(out+"/samples.csv");csv.precision(12);csv<<"test,src,dst,bytes,repeat,iterations,device_us,wall_us,gbps,tflops,valid\n";inventory(out+"/inventory.json");std::cout<<"inventory complete\n"<<std::flush;
 for(int g=0;g<3;++g){scheduling(g);memory(g);}std::cout<<"memory and launch tests complete\n"<<std::flush;barriers();transfers();std::cout<<"communication complete\n"<<std::flush;compute();overlap();std::ofstream(out+"/PASS")<<"All transfer payload, triad and GEMM checks passed\n";std::cout<<"PASS all benchmarks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
